RaceSnapshot sample(float time){RaceSnapshot s;s.active=s.demo=true;s.identity=999999;s.time=time;s.course=2400;s.trackName="Tokyo";s.groundType=1;s.groundCondition=1;s.weather=1;s.season=1;const char* names[]={"Oguri Cap","Oguri Cap","Gold Ship","Daiwa Scarlet","Mejiro McQueen","Kitasan Black","Rice Shower","Special Week","Silence Suzuka","Tokai Teio"};const char* variants[]={"Starlight Beat","Ashen Miracle","Red Strife","Peak Blue","Frontline Elegance","Gilded Shrine to Glory","Rosy Dreams","Special Dreamer","Innocent Silence","Peak Joy"};int cards[]={100601,100602,100701,100901,101301,106801,103001,100101,100201,100301};for(int i=0;i<10;i++){Runner r;r.id=i;r.gate=i+1;r.card=cards[i];r.name=names[i];r.variant=variants[i];r.trainer="Sample player "+std::to_string(i+1);r.style=i%4+1;r.distance=1500+(10-i)*3+8*std::sin(time*.7f+i*1.5f);r.speed=19.7f+std::sin(time+i);r.rushed=i==2;r.blocked=i==4;r.lateStart=i==3&&int(time)%12<4;r.staminaEmpty=i==5&&int(time)%10<4;s.runners.push_back(r);}std::sort(s.runners.begin(),s.runners.end(),[](auto&a,auto&b){return a.distance>b.distance;});for(size_t i=0;i<s.runners.size();i++)s.runners[i].rank=int(i)+1;return s;}
